<script>
// Mobile nav toggle
document.getElementById('mobileToggle').addEventListener('click', function() {
  document.getElementById('navLinks').classList.toggle('open');
  document.getElementById('navCta').classList.toggle('open');
  this.textContent = this.textContent === '☰' ? '✕' : '☰';
});

// Carousel
let currentSlide = 0;
const track = document.getElementById('carouselTrack');
const slides = track.children;
const totalSlides = slides.length;
const dotsContainer = document.getElementById('carouselDots');

for (let i = 0; i < totalSlides; i++) {
  const dot = document.createElement('button');
  dot.className = 'carousel-dot' + (i === 0 ? ' active' : '');
  dot.setAttribute('aria-label', 'Slide ' + (i + 1));
  dot.addEventListener('click', () => goToSlide(i));
  dotsContainer.appendChild(dot);
}

function goToSlide(index) {
  currentSlide = ((index % totalSlides) + totalSlides) % totalSlides;
  track.style.transform = 'translateX(-' + (currentSlide * 100) + '%)';
  document.querySelectorAll('.carousel-dot').forEach((d, i) => {
    d.classList.toggle('active', i === currentSlide);
  });
}

document.getElementById('carouselPrev').addEventListener('click', () => goToSlide(currentSlide - 1));
document.getElementById('carouselNext').addEventListener('click', () => goToSlide(currentSlide + 1));

// Touch swipe for carousel
let touchStartX = 0;
track.addEventListener('touchstart', e => { touchStartX = e.touches[0].clientX; });
track.addEventListener('touchend', e => {
  const diff = touchStartX - e.changedTouches[0].clientX;
  if (Math.abs(diff) > 50) goToSlide(currentSlide + (diff > 0 ? 1 : -1));
});

// Newsletter
document.getElementById('newsletterForm').addEventListener('submit', function(e) {
  e.preventDefault();
  const input = document.getElementById('newsletterEmail');
  const msg = document.getElementById('newsletterMsg');
  const email = input.value.trim();
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  input.classList.remove('error', 'success');
  msg.className = 'newsletter-msg';

  if (!email) {
    input.classList.add('error');
