});

// FAQ Accordion — single-open behavior
document.querySelectorAll('.faq-question').forEach(btn => {
  btn.addEventListener('click', function() {
    const item = this.parentElement;
    const isOpen = item.classList.contains('open');

    // Close all
    document.querySelectorAll('.faq-item').forEach(faq => faq.classList.remove('open'));

    // Open clicked (unless it was already open)
    if (!isOpen) {
      item.classList.add('open');
    }
  });
});

// Set initial open item's max-height
(function() {
  const openItem = document.querySelector('.faq-item.open');
  if (openItem) {
    const answer = openItem.querySelector('.faq-answer');
    const inner = openItem.querySelector('.faq-answer-inner');
    answer.style.maxHeight = inner.scrollHeight + 20 + 'px';
  }
})();

// Update answer max-heights when toggling
document.querySelectorAll('.faq-question').forEach(btn => {
  btn.addEventListener('click', function() {
    const answer = this.nextElementSibling;
    const inner = answer.querySelector('.faq-answer-inner');
    if (this.parentElement.classList.contains('open')) {
      answer.style.maxHeight = inner.scrollHeight + 20 + 'px';
    } else {
      answer.style.maxHeight = '0';
    }
  });
});

